stfont we created...	pha	phd	tsc	; get the stack pointer		sec	sbc #SizeOfFrame	tcd	; create the stack frame...	tcs	;; Now that the stack frame is set up, create the offscreen buffers that we are; going to use. Ask for a block the size of shaston 8 first!	stz Result	stz Result+2	pha	; room for result	pha	pea $0000	; size of block	pea $7000	; TEMP	pei uUserID	; pass the users ID on to the memory manager	pea $4008	; locked	pha	pha	_NewHandle		plx	pla	bcc @1	; if no error continue	ldx #-1	brl @ErrOut	; die with an error@1	stx deref1	stx Result	sta deref1+2	ora #$8000	sta Result+2	ldy #2	lda [deref1],y	tax	lda [deref1]	sta deref1	stx deref1+2	lda #0	pha	; room for refnum	pha	PushLong #FFPath	pha	tsc	pea 00	inc a	pha	pea $0010	jsl >$E100B0	tax	pla	; save the refnum	ply	ply	ply	ply	; discard the crap	bcs @ErrOut	sta refNum		lda #0	pha	pha	pha	pea $FFFF	pei deref1+2	pei deref1	pei refnum	tsc	pea 00	inc a	pha	pea $0012	jsl >$E100B0		plx	plx	plx	plx	plx	plx	plx	php	; save the read status its important	pei refnum	tsc	pea 00	inc a	pha	pea $0014	jsl >$E100B0		pla	plp	ldx #-1	bcs @ErrOut;; Make this stuff work right!	pha	pha	_GetSYSFont	ldy #o_oldFontHandle	pla	sta [deref1],y	pla	ldy #o_oldFontHandle+2	sta [Deref1],y	ldx #0@ErrOut		cpx #0	beq @okend	lda Result+2	and #$00FF	pha	pei Result	_DisposeHandle@okEnd	tdc	clc	adc #SizeOfFrame	tcs	pld	pla	txa	cmp #1	rtlFFPath	str '*/System/Fonts/FastFont'	EndP	END